package net.e175.klaus.solarpositioning;

import org.junit.Test;
import static org.junit.Assert.*;
import java.time.LocalDate;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public class DeltaTTest {

    @Test
    public void estimateForValidDate_ReturnsCorrectValue() {
        LocalDate forDate = LocalDate.of(2022, 6, 1);
        double actual = DeltaT.estimate(forDate);
        double expected = 10.536;
        assertEquals(expected, actual, 0.01);
    }

    @Test
    public void estimateForUnknownDate_ThrowsException() {
        LocalDate forDate = null;
        assertThrows(NullPointerException.class, () -> DeltaT.estimate(forDate));
    }

    @Test
    public void estimateForInvalidDate_ThrowsException() {
        LocalDate forDate = LocalDate.of(2022, 13, 1);
        assertThrows(IllegalArgumentException.class, () -> DeltaT.estimate(forDate));
    }

    @Test
    public void getDeltaTValues_ReturnsCorrectList() {
        List<Double> actual = DeltaT.getDeltaTValues(LocalDate.of(2022, 6, 1));
        List<Double> expected = List.of(10.536, 13.452);
        assertEquals(expected, actual);
    }

    @Test
    public void getDeltaTValues_NullDate_ReturnsEmptyList() {
        List<Double> actual = DeltaT.getDeltaTValues(null);
        assertTrue(actual.isEmpty());
    }

    @Test
    public void getDeltaTValues_EmptyDateRange_ReturnsEmptyList() {
        List<Double> actual = DeltaT.getDeltaTValues(LocalDate.of(2022, 6, 1), LocalDate.of(2022, 6, 1));
        assertTrue(actual.isEmpty());
    }
}

